def build_agent(sandbox):
    # Create main horizontal body at starting position
    main_body = sandbox.add_beam(x=4.5, y=1.5, width=2.0, height=0.4, density=7.0)

    # Create vertical segments with pivot joints for climbing
    prev_beam = main_body
    for i in range(5):
        # Calculate vertical position within build zone
        y_pos = 1.5 + (i + 1) * 1.0  # 1.0m spacing between segments
        beam = sandbox.add_beam(x=4.5, y=y_pos, width=0.4, height=3.0, density=7.0)
        # Connect with pivot joint at the bottom of the new beam
        joint = sandbox.add_joint(prev_beam, beam, (4.5, y_pos), type='pivot')
        # Store joint for control
        if i == 0:
            control_joint = joint
        prev_beam = beam

    # Add adhesive pads on the last vertical beam
    pad = sandbox.add_pad(x=4.5, y=1.5 + 5 * 1.0 + 1.5, radius=0.25, density=0.8)

    # Configure control parameters
    agent_body = {
        'main': main_body,
        'joint': control_joint,
        'p_torso': [pad],
        'p_arm': [],
        'cycle': 100,
        'overlap': 10,
        'speed': 5.0,  # Reduced speed to match joint torque limits
        'torque': 100.0  # Max allowed torque
    }
    return agent_body

