def _apply_climb_action(sandbox, agent_body, step_count):
    c = agent_body.get("control", {}) if isinstance(agent_body, dict) else {}
    if not c: return

    cycle = c['cycle']
    phase = step_count % (2 * cycle)
    overlap = c.get('overlap', 10)
    speed = c.get('speed', 5.0)
    torque = c.get('torque', 100.0)

    if phase < cycle:
        # Activate torso pad and motor
        for p in c['p_torso']:
            sandbox.set_pad_active(p, True)
        # Temporarily activate arm pads during overlap
        if phase > overlap:
            for p in c['p_arm']:
                sandbox.set_pad_active(p, False)
        else:
            for p in c['p_arm']:
                sandbox.set_pad_active(p, True)
        sandbox.set_motor(c['joint'], speed, torque)
    else:
        # Alternate pad activation in the second half of the cycle
        for p in c['p_arm']:
            sandbox.set_pad_active(p, True)
        if (phase - cycle) > overlap:
            for p in c['p_torso']:
                sandbox.set_pad_active(p, False)
        else:
            for p in c['p_torso']:
                sandbox.set_pad_active(p, True)
        sandbox.set_motor(c['joint'], -speed, torque)
